  wat_listening: { bg:'слуша ✓', ru:'слушаю ✓', uk:'слухаю ✓', en:'listening ✓', de:'höre zu ✓', fr:'à l’écoute ✓', es:'escuchando ✓', 'es-MX':'escuchando ✓', it:'in ascolto ✓', pt:'ouvindo ✓', ar:'يستمع ✓', hi:'सुन रहा है ✓', ja:'待機中 ✓', ky:'угуп жатат ✓', 'zh-Hant':'監聽中 ✓' },
  wat_waiting: { bg:'Още няма събития. Чакам сигнал от камерата…', ru:'Событий пока нет. Жду сигнал с камеры…', uk:'Подій поки немає. Чекаю сигнал з камери…', en:'No events yet. Waiting for a signal from the camera…', de:'Noch keine Ereignisse. Warte auf ein Signal von der Kamera…', fr:'Aucun événement pour l’instant. En attente d’un signal de la caméra…', es:'Aún no hay eventos. Esperando una señal de la cámara…', 'es-MX':'Aún no hay eventos. Esperando una señal de la cámara…', it:'Ancora nessun evento. In attesa di un segnale dalla telecamera…', pt:'Ainda sem eventos. Aguardando um sinal da câmera…', ar:'لا أحداث بعد. في انتظار إشارة من الكاميرا…', hi:'अभी कोई घटना नहीं। कैमरे से संकेत की प्रतीक्षा…', ja:'まだイベントはありません。カメラからの信号を待機中…', ky:'Азырынча окуялар жок. Камерадан сигнал күтүүдө…', 'zh-Hant':'尚無事件。等待相機的訊號…' },
  wat_last_frame: { bg:'Последен кадър от камерата', ru:'Последний кадр с камеры', uk:'Останній кадр з камери', en:'Last frame from the camera', de:'Letztes Bild der Kamera', fr:'Dernière image de la caméra', es:'Último fotograma de la cámara', 'es-MX':'Último fotograma de la cámara', it:'Ultimo fotogramma della telecamera', pt:'Último quadro da câmera', ar:'آخر إطار من الكاميرا', hi:'कैमरे का अंतिम फ़्रेम', ja:'カメラの最後のフレーム', ky:'Камеранын акыркы кадры', 'zh-Hant':'相機的最後一格畫面' },

